package com.smartexam.teacher;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.smartexam.entity.*;import com.smartexam.mapper.ExamCandidatesMapper;import com.smartexam.security.JwtService;import com.smartexam.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest @AutoConfigureMockMvc @Transactional class TeacherDashboardIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired UsersService users;@Autowired CoursesService courses;@Autowired ExamsService exams;@Autowired QuestionsService questions;@Autowired SubmissionsService submissions;@Autowired AnswersService answers;@Autowired ExamCandidatesMapper candidates;@Autowired JwtService jwt;
 Users teacher;String token;Long courseId;
 @BeforeEach void setup(){teacher=users.findByUsername("teacher_demo");token=jwt.generate(teacher);Courses c=new Courses();c.setTeacherId(teacher.getId());c.setCourseName("任务工作台课程");courses.save(c);courseId=c.getId();}
 @Test void classifiesPendingReadyAndOngoingWithoutOverlap()throws Exception{Exams pending=exam(-120,-30),ready=exam(-120,-30),ongoing=exam(-10,50);Users a=student("待阅"),b=student("已阅");candidate(pending,a);submission(pending,a,"SUBMITTED");candidate(ready,b);submission(ready,b,"GRADED");JsonNode data=dashboard(token);assertIds(data.path("pendingReview"),pending.getId());assertIds(data.path("readyToRelease"),ready.getId());assertIds(data.path("ongoing"),ongoing.getId());assertThat(data.path("pendingReview").toString()).doesNotContain(ready.getId().toString(),ongoing.getId().toString());}
 @Test void releasedExamIsExcludedFromActionLists()throws Exception{Exams released=exam(-120,-30);released.setResultsReleasedAt(LocalDateTime.now());exams.updateById(released);JsonNode data=dashboard(token);assertThat(data.path("pendingReview")).noneMatch(row->row.path("examId").asLong()==released.getId());assertThat(data.path("readyToRelease")).noneMatch(row->row.path("examId").asLong()==released.getId());}
 @Test void absentCandidatesDoNotBecomePendingReview()throws Exception{Exams ready=exam(-120,-30);List<Users> rows=List.of(student("一"),student("二"),student("三"),student("缺考一"),student("缺考二"));rows.forEach(s->candidate(ready,s));for(int i=0;i<3;i++)submission(ready,rows.get(i),"GRADED");JsonNode item=find(dashboard(token).path("readyToRelease"),ready.getId());assertThat(item.path("candidateCount").asInt()).isEqualTo(5);assertThat(item.path("submittedCount").asInt()).isEqualTo(3);assertThat(item.path("pendingReviewCount").asInt()).isZero();assertThat(item.path("canReleaseResults").asBoolean()).isTrue();}
 @Test void dashboardOnlyContainsCurrentTeachersExams()throws Exception{Users other=user("TEACHER","隔离教师");Courses c=new Courses();c.setTeacherId(other.getId());c.setCourseName("其他课程");courses.save(c);Long original=courseId;courseId=c.getId();Exams foreign=exam(-10,30);courseId=original;JsonNode data=dashboard(token);assertThat(data.toString()).doesNotContain(foreign.getId().toString(),"其他课程");}
 JsonNode dashboard(String bearer)throws Exception{return json.readTree(mvc.perform(get("/api/teacher/dashboard").header("Authorization","Bearer "+bearer)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).path("data");}
 void assertIds(JsonNode rows,Long id){assertThat(rows).anyMatch(row->row.path("examId").asLong()==id);}
 JsonNode find(JsonNode rows,Long id){for(JsonNode row:rows)if(row.path("examId").asLong()==id)return row;throw new AssertionError("missing exam "+id);}
 Exams exam(int startMinutes,int endMinutes){Exams e=new Exams();e.setCourseId(courseId);e.setCreatedBy(teacher.getId());e.setTitle("任务考试"+UUID.randomUUID().toString().substring(0,4));e.setStartTime(LocalDateTime.now().plusMinutes(startMinutes));e.setEndTime(LocalDateTime.now().plusMinutes(endMinutes));e.setLateEntryMinutes(0);e.setMinSubmitMinutes(0);e.setStatus("PUBLISHED");exams.save(e);Questions q=new Questions();q.setExamId(e.getId());q.setQuestionType("SINGLE_CHOICE");q.setContent("题目");q.setScore(BigDecimal.TEN);q.setSortOrder(1);questions.save(q);Questions s=new Questions();s.setExamId(e.getId());s.setQuestionType("SHORT_ANSWER");s.setContent("简答题");s.setScore(BigDecimal.TEN);s.setSortOrder(2);questions.save(s);return e;}
 Users student(String name){return user("STUDENT",name);}Users user(String role,String name){Users u=new Users();u.setUsername("dashboard_"+UUID.randomUUID().toString().substring(0,8));u.setName(name);u.setRole(role);u.setStatus(1);u.setPasswordHash(teacher.getPasswordHash());users.save(u);return u;}
 void candidate(Exams e,Users s){ExamCandidate c=new ExamCandidate();c.setExamId(e.getId());c.setStudentId(s.getId());candidates.insert(c);}
 void submission(Exams e,Users s,String status){Submissions row=new Submissions();row.setExamId(e.getId());row.setStudentId(s.getId());row.setFirstEnterTime(LocalDateTime.now().minusMinutes(20));row.setLastEnterTime(LocalDateTime.now().minusMinutes(10));row.setSubmitTime(LocalDateTime.now().minusMinutes(5));row.setStatus(status);row.setTotalScore(BigDecimal.TEN);row.setScorePublished(0);submissions.save(row);for(Questions q:questions.findByExamId(e.getId())){Answers a=new Answers();a.setSubmissionId(row.getId());a.setQuestionId(q.getId());if("SINGLE_CHOICE".equals(q.getQuestionType())){a.setAutoScore(BigDecimal.TEN);a.setGradingStatus("AUTO_GRADED");}else if("SHORT_ANSWER".equals(q.getQuestionType())&&"GRADED".equals(status)){a.setTeacherScore(BigDecimal.TEN);a.setGradingStatus("REVIEWED");}else a.setGradingStatus("PENDING");answers.save(a);}}
}
